={{
  {
    systemInstruction: {
      parts: [
        {
          text: $json.planning_request.system_prompt
        }
      ]
    },
    contents: [
      {
        role: "user",
        parts: [
          {
            text: $json.planning_request.user_prompt
          }
        ]
      }
    ],
    generationConfig: {
      responseMimeType: "application/json",
      responseJsonSchema: {
        type: "object",
        additionalProperties: false,
        properties: {
          scenes: {
            type: "array",
            minItems: $json.planning_request.required_scene_count,
            maxItems: $json.planning_request.required_scene_count,
            prefixItems: $json.planning_request.scene_word_counts.map(
              (wordCount, index) => ({
                type: "object",
                additionalProperties: false,
                properties: {
                  scene_number: {
                    type: "integer",
                    minimum: index + 1,
                    maximum: index + 1
                  },
                  narration_words: {
                    type: "array",
                    minItems: wordCount,
                    maxItems: wordCount,
                    description: `Exactly ${wordCount} one-word spoken tokens in ${$json.planning_request.language_name}. Punctuation must be attached to a word.`,
                    items: {
                      type: "string"
                    }
                  },
                  visual_subject_type: {
                    type: "string",
                    enum: [
                      "factual",
                      "generic"
                    ]
                  },
                  visual_description: {
                    type: "string"
                  },
                  visual_query: {
                    type: "string"
                  }
                },
                required: [
                  "scene_number",
                  "narration_words",
                  "visual_subject_type",
                  "visual_description",
                  "visual_query"
                ]
              })
            )
          }
        },
        required: [
          "scenes"
        ]
      }
    }
  }
}}

parameters.jsCode:
const response = $input.first().json;
const job = $('Build Planning Request').first().json;

if (
  !job ||
  typeof job.job_id !== 'string' ||
  job.job_id.trim() === ''
) {
  throw new Error('Original job data is unavailable');
}

const requiredScenesByDuration = {
  15: 4,
  30: 8,
  45: 12,
  60: 15,
};

const targetDurationSeconds = Number(
  job.target_duration_seconds
);
const requiredSceneCount =
  requiredScenesByDuration[targetDurationSeconds];
const sceneWordCounts =
  job.planning_request?.scene_word_counts;
const expectedTotalNarrationWords = Number(
  job.planning_request?.total_narration_words
);

if (!requiredSceneCount) {
  throw new Error(
    `Unsupported target_duration_seconds: ${job.target_duration_seconds}`
  );
}

if (
  job.planning_request?.required_scene_count !==
  requiredSceneCount
) {
  throw new Error(
    `Planning request scene count mismatch: expected ${requiredSceneCount}, received ${job.planning_request?.required_scene_count}`
  );
}

if (
  !Array.isArray(sceneWordCounts) ||
  sceneWordCounts.length !== requiredSceneCount ||
  sceneWordCounts.some(
    (value) => !Number.isInteger(value) || value <= 0
  ) ||
  expectedTotalNarrationWords !==
    sceneWordCounts.reduce((sum, value) => sum + value, 0)
) {
  throw new Error('Planning request word budget is invalid');
}

if (
  !Array.isArray(response.candidates) ||
  response.candidates.length !== 1
) {
  throw new Error(
    'Gemini response must contain exactly one candidate'
  );
}

const candidate = response.candidates[0];

if (candidate.finishReason !== 'STOP') {
  throw new Error(
    `Gemini generation did not finish normally: ${
      candidate.finishReason ?? 'missing finishReason'
    }`
  );
}

const parts = candidate.content?.parts;

if (!Array.isArray(parts)) {
  throw new Error(
    'Gemini response does not contain content.parts'
  );
}

const textParts = parts.filter(
  (part) =>
    typeof part?.text === 'string' &&
    part.text.trim() !== ''
);

if (textParts.length !== 1) {
  throw new Error(
    `Expected exactly one non-empty text part, received ${textParts.length}`
  );
}

let plan;

try {
  plan = JSON.parse(textParts[0].text);
} catch (error) {
  throw new Error(
    `Gemini returned invalid JSON: ${error.message}`
  );
}

if (
  plan === null ||
  typeof plan !== 'object' ||
  Array.isArray(plan)
) {
  throw new Error(
    'Planning result must be a JSON object'
  );
}

const rootKeys = Object.keys(plan);

if (
  rootKeys.length !== 1 ||
  !Object.prototype.hasOwnProperty.call(
    plan,
    'scenes'
  )
) {
  throw new Error(
    'Planning result must contain only the scenes property'
  );
}

if (!Array.isArray(plan.scenes)) {
  throw new Error(
    'Planning result scenes must be an array'
  );
}

if (plan.scenes.length !== requiredSceneCount) {
  throw new Error(
    `Planning result must contain exactly ${requiredSceneCount} scenes for ${targetDurationSeconds} seconds; received ${plan.scenes.length}`
  );
}

const requiredSceneFields = [
  'scene_number',
  'narration_words',
  'visual_subject_type',
  'visual_description',
  'visual_query',
];

const allowedSubjectTypes = new Set([
  'factual',
  'generic',
]);
const seenVisualQueries = new Set();
let actualNarrationWordCount = 0;
let totalExtraWordsFromPackedItems = 0;

const scenes = plan.scenes.map((scene, index) => {
  const expectedSceneNumber = index + 1;

  if (
    scene === null ||
    typeof scene !== 'object' ||
    Array.isArray(scene)
  ) {
    throw new Error(
      `Scene ${expectedSceneNumber} must be an object`
    );
  }

  const sceneKeys = Object.keys(scene);
  const missingFields = requiredSceneFields.filter(
    (field) =>
      !Object.prototype.hasOwnProperty.call(
        scene,
        field
      )
  );
  const unexpectedFields = sceneKeys.filter(
    (field) =>
      !requiredSceneFields.includes(field)
  );

  if (missingFields.length > 0) {
    throw new Error(
      `Scene ${expectedSceneNumber} is missing fields: ${missingFields.join(', ')}`
    );
  }

  if (unexpectedFields.length > 0) {
    throw new Error(
      `Scene ${expectedSceneNumber} contains unexpected fields: ${unexpectedFields.join(', ')}`
    );
  }

  if (
    !Number.isInteger(scene.scene_number) ||
    scene.scene_number !== expectedSceneNumber
  ) {
    throw new Error(
      `Scene number must be sequential: expected ${expectedSceneNumber}, received ${scene.scene_number}`
    );
  }

  if (!Array.isArray(scene.narration_words)) {
    throw new Error(
      `Scene ${expectedSceneNumber} narration_words must be an array`
    );
  }

  const expectedSceneWordCount =
    sceneWordCounts[index];

  if (scene.narration_words.length !== expectedSceneWordCount) {
    throw new Error(
      `Scene ${expectedSceneNumber} narration_words must contain exactly ${expectedSceneWordCount} items; received ${scene.narration_words.length}`
    );
  }

  const narrationWords = [];

  for (let wordIndex = 0; wordIndex < scene.narration_words.length; wordIndex++) {
    const packedToken =
      typeof scene.narration_words[wordIndex] === 'string'
        ? scene.narration_words[wordIndex].trim()
        : '';

    if (!packedToken) {
      throw new Error(
        `Scene ${expectedSceneNumber} narration word ${wordIndex + 1} is empty or invalid`
      );
    }

    const unpackedWords = packedToken.split(/\s+/u);

    if (unpackedWords.length > 2) {
      throw new Error(
        `Scene ${expectedSceneNumber} narration item ${wordIndex + 1} contains too many packed words: ${packedToken}`
      );
    }

    for (const token of unpackedWords) {
      if (!/[\p{L}\p{N}]/u.test(token)) {
        throw new Error(
          `Scene ${expectedSceneNumber} narration item ${wordIndex + 1} contains punctuation-only content: ${token}`
        );
      }

      narrationWords.push(token);
    }
  }

  const extraWordsInScene =
    narrationWords.length - expectedSceneWordCount;

  if (extraWordsInScene < 0 || extraWordsInScene > 1) {
    throw new Error(
      `Scene ${expectedSceneNumber} contains ${narrationWords.length} spoken words for a ${expectedSceneWordCount}-unit budget`
    );
  }

  actualNarrationWordCount += narrationWords.length;
  totalExtraWordsFromPackedItems += extraWordsInScene;

  const narration = narrationWords.join(' ');
  const visualDescription =
    typeof scene.visual_description === 'string'
      ? scene.visual_description.trim()
      : '';
  const visualQuery =
    typeof scene.visual_query === 'string'
      ? scene.visual_query.trim()
      : '';

  if (!narration) {
    throw new Error(
      `Scene ${expectedSceneNumber} has empty narration after joining words`
    );
  }

  if (!visualDescription) {
    throw new Error(
      `Scene ${expectedSceneNumber} has an empty or invalid visual_description`
    );
  }

  if (!visualQuery) {
    throw new Error(
      `Scene ${expectedSceneNumber} has an empty or invalid visual_query`
    );
  }

  if (
    typeof scene.visual_subject_type !== 'string' ||
    !allowedSubjectTypes.has(scene.visual_subject_type)
  ) {
    throw new Error(
      `Scene ${expectedSceneNumber} has invalid visual_subject_type: ${scene.visual_subject_type}`
    );
  }

  if (visualQuery.length > 100) {
    throw new Error(
      `Scene ${expectedSceneNumber} visual_query exceeds 100 characters: ${visualQuery.length}`
    );
  }

  const normalizedVisualQuery = visualQuery.toLowerCase();
  if (seenVisualQueries.has(normalizedVisualQuery)) {
    throw new Error(
      `Scene ${expectedSceneNumber} duplicates visual_query case-insensitively: ${visualQuery}`
    );
  }
  seenVisualQueries.add(normalizedVisualQuery);

  return {
    scene_number: expectedSceneNumber,
    narration,
    visual_subject_type: scene.visual_subject_type,
    visual_description: visualDescription,
    visual_query: visualQuery,
  };
});

const plannedNarrationWordUnits = sceneWordCounts.reduce(
  (sum, value) => sum + value,
  0
);

if (plannedNarrationWordUnits !== expectedTotalNarrationWords) {
  throw new Error(
    `Planning narration unit count mismatch: expected ${expectedTotalNarrationWords}, received ${plannedNarrationWordUnits}`
  );
}

const maximumPackedExtraWords = Math.max(
  1,
  Math.ceil(requiredSceneCount / 4)
);

if (
  actualNarrationWordCount < plannedNarrationWordUnits ||
  totalExtraWordsFromPackedItems > maximumPackedExtraWords ||
  actualNarrationWordCount >
    plannedNarrationWordUnits + maximumPackedExtraWords
) {
  throw new Error(
    `Planning narration expanded to ${actualNarrationWordCount} spoken words from ${plannedNarrationWordUnits} schema units; allowed extra words=${maximumPackedExtraWords}`
  );
}

const totalNarrationCharacters = scenes.reduce(
  (sum, scene) => sum + scene.narration.length,
  0
);

return [
  {
    json: {
      job_id: job.job_id,
      topic: job.topic,
      language_code: job.language_code,
      target_duration_seconds: targetDurationSeconds,
      status: job.status,
      current_stage: job.current_stage,
      scenes,
      narration_word_count: actualNarrationWordCount,
      narration_word_unit_budget: plannedNarrationWordUnits,
      narration_packed_extra_words: totalExtraWordsFromPackedItems,
      narration_word_counts_by_scene: sceneWordCounts,
      narration_character_count: totalNarrationCharacters,
      narration_word_budget_source:
        job.planning_request.narration_word_budget_source,
      ai_metadata: {
        provider: 'google_gemini',
        model: response.modelVersion ?? null,
        response_id: response.responseId ?? null,
        prompt_tokens:
          response.usageMetadata?.promptTokenCount ?? null,
        output_tokens:
          response.usageMetadata?.candidatesTokenCount ?? null,
        total_tokens:
          response.usageMetadata?.totalTokenCount ?? null,
      },
    },
  },
];
